// src/pages/catalog/catalogDetail.tsx
import { useMemo, useState, Suspense } from 'react'
import { TabList } from '@os/ui/TabList'
import { CodeViewer } from '@os/ui/CodeViewer'
import { ax } from '@styles/ax'
import type { CatalogEntry } from './catalogTypes'
import { demoSources } from '@/pages/creator/demoRegistry'

interface Props { entry: CatalogEntry | null }

type TabKey = 'preview' | 'source' | 'gaps' | 'docs'

export function CatalogDetail({ entry }: Props) {
  const [tab, setTab] = useState<TabKey>('preview')
  if (!entry) return <div className={ax({ padding: 'lg', text: 'secondary' })}>컴포넌트를 선택하세요</div>

  return (
    <div className={ax({ stack: 'vertical', gap: 'md', padding: 'md' })}>
      <TabList
        items={[
          { id: 'preview', label: 'Preview' },
          { id: 'source', label: 'Source' },
          { id: 'gaps', label: 'Gaps' },
          { id: 'docs', label: 'Docs' },
        ]}
        selectedId={tab}
        onSelect={(id) => setTab(id as TabKey)}
      />
      {tab === 'preview' && <PreviewPane entry={entry} />}
      {tab === 'source' && <SourcePane entry={entry} />}
      {tab === 'gaps' && <GapsPane entry={entry} />}
      {tab === 'docs' && <DocsPane entry={entry} />}
    </div>
  )
}
